      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-8">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-[#0D1B3E] text-white rounded-xl flex items-center justify-center shadow-md">
            <FiBookOpen size={22} />
          </div>

          <div>
            <h1 className="text-2xl md:text-3xl font-bold text-[#0D1B3E]">
              {tr(
                'courses.title',
                'Courses Management',
                'គ្រប់គ្រងវគ្គសិក្សា'
              )}
            </h1>

            <p className="text-sm text-[#6B8AFF] mt-0.5">
              {tr(
                'courses.subtitle',
                'Manage courses and course categories',
                'គ្រប់គ្រងវគ្គសិក្សា និងមាតិកា YouTube'
              )}
            </p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <button
            type="button"
            onClick={handleAddCategory}
            className="h-11 px-5 inline-flex items-center justify-center gap-2 bg-white text-[#0D1B3E] rounded-lg text-sm font-semibold hover:bg-gray-50 transition shadow-sm border border-[#E8EEF9]"
          >
            <FiPlus size={18} />

            {tr(
              'courses.addCategory',
              'Add Category',
              'បន្ថែមប្រភេទ'
            )}
          </button>

          <button
            type="button"
            onClick={handleAddCourse}
            className="h-11 px-5 inline-flex items-center justify-center gap-2 bg-[#C23636] text-white rounded-lg text-sm font-semibold hover:bg-[#A92E2E] transition shadow-sm"
          >
            <FiPlus size={18} />

            {tr(
              'courses.addCourse',
              'Add Course',
              'បន្ថែមវគ្គសិក្សា'
            )}
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 xl:grid-cols-4 gap-5 mb-8">
        <div className="bg-white rounded-xl p-5 shadow-sm border border-[#F0F4FB]">
          <div>
            <p className="text-sm text-[#6B8AFF] mb-1">
              {tr(
                'courses.totalCourses',
                'Total Courses',
                'វគ្គសិក្សាសរុប'
              )}
            </p>

            <p className="text-2xl font-bold text-[#0D1B3E]">
              {courses.length}
            </p>
          </div>
        </div>

        <div className="bg-white rounded-xl p-5 shadow-sm border border-[#F0F4FB]">
          <div>
            <p className="text-sm text-[#6B8AFF] mb-1">
              {tr(
                'courses.activeCourses',
                'Active Courses',
                'វគ្គសិក្សាសកម្ម'
              )}
            </p>

            <p className="text-2xl font-bold text-[#0D1B3E]">
              {activeCourses}
            </p>
          </div>
        </div>

        <div className="bg-white rounded-xl p-5 shadow-sm border border-[#F0F4FB]">
          <div>
            <p className="text-sm text-[#6B8AFF] mb-1">
              {tr(
                'courses.featuredCourses',
                'Featured',
                'វគ្គសិក្សាពិសេស'
              )}
            </p>

            <p className="text-2xl font-bold text-[#0D1B3E]">
              {featuredCourses}
            </p>
          </div>
        </div>

        <div className="bg-white rounded-xl p-5 shadow-sm border border-[#F0F4FB]">
          <div>
            <p className="text-sm text-[#6B8AFF] mb-1">
              {tr(
                'courses.categories',
                'Categories',
                'ប្រភេទវគ្គសិក្សា'
              )}
            </p>

            <p className="text-2xl font-bold text-[#0D1B3E]">
              {activeCategories}
            </p>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex items-center gap-2 mb-6 p-1 bg-white rounded-xl shadow-sm w-fit border border-[#F0F4FB]">
        <button
          type="button"
          onClick={() =>
            setActiveTab('courses')
          }
          className={`
            h-10
            px-5
            rounded-lg
            text-sm
            font-semibold
            flex
            items-center
            gap-2
            transition
            ${
              activeTab === 'courses'
                ? 'bg-[#0D1B3E] text-white shadow-sm'
                : 'text-[#6B8AFF] hover:bg-[#F0F7FF]'
            }
          `}
        >
          <FiBookOpen size={16} />

          {tr(
            'courses.courses',
            'Courses',
            'វគ្គសិក្សា'
          )}

          <span
            className={`
              min-w-[22px]
              h-6
              px-1
              rounded-md
              text-xs
              flex
              items-center
              justify-center
              ${
                activeTab === 'courses'
                  ? 'bg-white/20'
                  : 'bg-white'
              }
            `}
          >
            {courses.length}
          </span>
        </button>

        <button
          type="button"
          onClick={() =>
            setActiveTab('categories')
          }
          className={`
            h-10
            px-5
            rounded-lg
            text-sm
            font-semibold
            flex
            items-center
            gap-2
            transition
            ${
              activeTab === 'categories'
                ? 'bg-[#0D1B3E] text-white shadow-sm'
                : 'text-[#6B8AFF] hover:bg-[#F0F7FF]'
            }
          `}
        >
          <FiLayers size={16} />

          {tr(
            'courses.categories',
            'Categories',
            'ប្រភេទ'
          )}

          <span
            className={`
              min-w-[22px]
              h-6
              px-1
              rounded-md
              text-xs
              flex
              items-center
              justify-center
              ${
                activeTab === 'categories'
                  ? 'bg-white/20'
                  : 'bg-white'
              }
            `}
          >
            {categories.length}
          </span>
        </button>
      </div>

      {/* Main Table Card */}
      <AdminCard className="bg-white rounded-xl overflow-hidden shadow-sm border border-[#F0F4FB]">
        {activeTab === 'courses' ? (
          <AdminTable
            columns={courseColumns}
            data={courses}
            loading={loading}
          />
        ) : (
          <AdminTable
            columns={categoryColumns}
            data={categories}
            loading={loading}
          />
        )}
      </AdminCard>

      <AdminModal
        isOpen={courseModalOpen}
        onClose={closeCourseModal}
        title={
          editingCourse
            ? tr(
                'courses.editCourse',
                'Edit Course',
                'កែប្រែវគ្គសិក្សា'
              )
            : tr(
                'courses.createCourse',
                'Create Course',
                'បង្កើតវគ្គសិក្សា'
              )
        }
      >
        <form onSubmit={handleCourseSubmit}>
          <div className="space-y-5">
            <div className="border border-[#E8EEF9] rounded-xl overflow-hidden bg-white">
              <div className="flex items-center gap-2 px-4 py-3 bg-[#F0F7FF] border-b border-[#E8EEF9]">
                <FiGlobe className="text-[#0D1B3E]" />

                <h3 className="text-sm font-bold text-[#0D1B3E]">
                  {isKhmer
                    ? 'មាតិកាភាសាខ្មែរ'
                    : 'English Content'}
                </h3>
              </div>

              <div className="p-4 space-y-4">
                <div>
                  <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                    {isKhmer
                      ? 'ចំណងជើងវគ្គសិក្សា'
                      : 'Course Title'}

                    <span className="text-[#C23636] ml-1">
                      *
                    </span>
                  </label>

                  <input
                    type="text"
                    name={`title_${langSuffix}`}
                    value={
                      courseFormData[
                        `title_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCourseInputChange
                    }
                    className={`w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'ការអភិវឌ្ឍគេហទំព័រ'
                        : 'Web Development'
                    }
                    required
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                    {isKhmer
                      ? 'ការពិពណ៌នាខ្លី'
                      : 'Short Description'}
                  </label>

                  <textarea
                    name={`short_description_${langSuffix}`}
                    value={
                      courseFormData[
                        `short_description_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCourseInputChange
                    }
                    rows={2}
                    className={`w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition resize-none ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'បញ្ចូលការពិពណ៌នាខ្លីអំពីវគ្គសិក្សា'
                        : 'Short course description'
                    }
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                    {isKhmer
                      ? 'ការពិពណ៌នា'
                      : 'Description'}
                  </label>

                  <textarea
                    name={`description_${langSuffix}`}
                    value={
                      courseFormData[
                        `description_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCourseInputChange
                    }
                    rows={4}
                    className={`w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition resize-none ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'បញ្ចូលការពិពណ៌នាពេញលេញអំពីវគ្គសិក្សា'
                        : 'Enter full course description'
                    }
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                      {isKhmer
                        ? 'រយៈពេល'
                        : 'Duration'}
                    </label>

                    <input
                      type="text"
                      name={`duration_${langSuffix}`}
                      value={
                        courseFormData[
                          `duration_${langSuffix}`
                        ]
                      }
                      onChange={
                        handleCourseInputChange
                      }
                      className={`w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition ${
                        isKhmer
                          ? 'font-khmer'
                          : 'font-english'
                      }`}
                      placeholder={
                        isKhmer
                          ? '៣ ខែ'
                          : '3 Months'
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                      {isKhmer
                        ? 'កម្រិត'
                        : 'Level'}
                    </label>

                    <input
                      type="text"
                      name={`level_${langSuffix}`}
                      value={
                        courseFormData[
                          `level_${langSuffix}`
                        ]
                      }
                      onChange={
                        handleCourseInputChange
                      }
                      className={`w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition ${
                        isKhmer
                          ? 'font-khmer'
                          : 'font-english'
                      }`}
                      placeholder={
                        isKhmer
                          ? 'កម្រិតដំបូង'
                          : 'Beginner'
                      }
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="border border-[#E8EEF9] rounded-xl p-4 bg-white space-y-4">
              <h3 className="text-sm font-bold text-[#0D1B3E]">
                {tr(
                  'courses.generalInformation',
                  'General Information',
                  'ព័ត៌មានទូទៅ'
                )}
              </h3>

              <div>
                <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                  Slug *
                </label>

                <input
                  type="text"
                  name="slug"
                  value={courseFormData.slug}
                  onChange={
                    handleCourseInputChange
                  }
                  className="w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition"
                  placeholder="web-development"
                  required
                />
              </div>

              <div>
                <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                  {tr(
                    'courses.category',
                    'Category',
                    'ប្រភេទ'
                  )}

                  <span className="text-[#C23636] ml-1">
                    *
                  </span>
                </label>

                <select
                  name="category_id"
                  value={
                    courseFormData.category_id
                  }
                  onChange={
                    handleCourseInputChange
                  }
                  className="w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition"
                  required
                >
                  <option value="">
                    {tr(
                      'courses.selectCategory',
                      'Select Category',
                      'ជ្រើសរើសប្រភេទ'
                    )}
                  </option>

                  {categories.length === 0 ? (
                    <option value="" disabled>
                      {tr(
                        'courses.noCategoriesAvailable',
                        'No categories available',
                        'No categories available'
                      )}
                    </option>
                  ) : (
                    categories.map((category) => (
                      <option
                        key={category.id}
                        value={category.id}
                      >
                        {getCategoryOptionLabel(
                          category
                        )}
                      </option>
                    ))
                  )}
                </select>

                {categories.length === 0 && (
                  <button
                    type="button"
                    onClick={() => {
                      closeCourseModal();
                      resetCategoryForm();
                      setActiveTab('categories');
                      setCategoryModalOpen(true);
                    }}
                    className="mt-2 text-xs font-semibold text-[#6B8AFF] hover:text-[#0D1B3E] transition"
                  >
                    {tr(
                      'courses.createCategoryFirst',
                      'Create a category first',
                      'Create a category first'
                    )}
                  </button>
                )}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                    {tr(
                      'courses.price',
                      'Price',
                      'តម្លៃ'
                    )}
                  </label>

                  <input
                    type="text"
                    name="price"
                    value={courseFormData.price}
                    onChange={
                      handleCourseInputChange
                    }
                    className="w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition"
                    placeholder="0"
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                    {tr(
                      'courses.displayOrder',
                      'Display Order',
                      'លំដាប់បង្ហាញ'
                    )}
                  </label>

                  <input
                    type="number"
                    name="order"
                    min="0"
                    value={courseFormData.order}
                    onChange={
                      handleCourseInputChange
                    }
                    className="w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition"
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                {tr(
                  'courses.courseImage',
                  'Course Image',
                  'រូបភាពវគ្គសិក្សា'
                )}
              </label>

              {!courseImagePreview ? (
                <div
                  onClick={() =>
                    courseFileRef.current?.click()
                  }
                  className="min-h-[150px] border-2 border-dashed border-[#E8EEF9] rounded-xl flex flex-col items-center justify-center cursor-pointer bg-[#F0F7FF] hover:border-[#0D1B3E] transition"
                >
                  <input
                    ref={courseFileRef}
                    type="file"
                    accept="image/jpeg,image/jpg,image/png,image/webp"
                    onChange={
                      handleCourseImageChange
                    }
                    className="hidden"
                  />

                  <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-[#0D1B3E] border border-[#E8EEF9] mb-3">
                    <FiUploadCloud size={23} />
                  </div>

                  <p className="text-sm font-semibold text-[#0D1B3E]">
                    {tr(
                      'courses.uploadImage',
                      'Upload Course Image',
                      'បញ្ចូលរូបភាពវគ្គសិក្សា'
                    )}
                  </p>

                  <p className="text-xs text-[#6B8AFF] mt-1">
                    JPG, JPEG, PNG, WEBP — 5 MB
                  </p>
                </div>
              ) : (
                <div className="relative h-[220px] rounded-xl overflow-hidden border border-[#E8EEF9] bg-[#F0F7FF] group">
                  <img
                    src={courseImagePreview}
                    alt="Course Preview"
                    className="w-full h-full object-cover"
                  />

                  <button
                    type="button"
                    onClick={removeCourseImage}
                    className="absolute top-3 right-3 w-9 h-9 rounded-lg bg-[#C23636] text-white flex items-center justify-center hover:bg-[#A92E2E] shadow"
                  >
                    <FiX size={18} />
                  </button>

                  <button
                    type="button"
                    onClick={() =>
                      courseFileRef.current?.click()
                    }
                    className="absolute bottom-3 right-3 h-9 px-3 bg-white text-[#0D1B3E] rounded-lg text-xs font-semibold shadow"
                  >
                    {tr(
                      'courses.changeImage',
                      'Change Image',
                      'ប្ដូររូបភាព'
                    )}
                  </button>

                  <input
                    ref={courseFileRef}
                    type="file"
                    accept="image/jpeg,image/jpg,image/png,image/webp"
                    onChange={
                      handleCourseImageChange
                    }
                    className="hidden"
                  />
                </div>
              )}
            </div>

            <div className="flex flex-col gap-3">
              <label className="flex items-center justify-between gap-3 p-4 border border-[#E8EEF9] rounded-xl bg-white cursor-pointer hover:bg-[#F0F7FF] transition">
                <div className="flex items-center gap-3">
                  <div
                    className={`
                      w-9
                      h-9
                      rounded-lg
                      flex
                      items-center
                      justify-center
                      ${
                        courseFormData.is_active
                          ? 'bg-[#EBF9F0] text-[#2E7D32]'
                          : 'bg-[#F0F7FF] text-[#6B8AFF]'
                      }
                    `}
                  >
                    {courseFormData.is_active ? (
                      <FiCheckCircle />
                    ) : (
                      <FiXCircle />
                    )}
                  </div>

                  <div>
                    <p className="text-sm font-semibold text-[#0D1B3E]">
                      {tr(
                        'courses.activeCourse',
                        'Active Course',
                        'វគ្គសិក្សាសកម្ម'
                      )}
                    </p>

                    <p className="text-xs text-[#6B8AFF]">
                      {tr(
                        'courses.activeCourseHelp',
                        'Show this course on the website',
                        'បង្ហាញវគ្គសិក្សានេះនៅលើគេហទំព័រ'
                      )}
                    </p>
                  </div>
                </div>

                <input
                  type="checkbox"
                  name="is_active"
                  checked={
                    courseFormData.is_active
                  }
                  onChange={
                    handleCourseInputChange
                  }
                  className="w-4 h-4 accent-[#0D1B3E]"
                />
              </label>

              <label className="flex items-center justify-between gap-3 p-4 border border-[#E8EEF9] rounded-xl bg-white cursor-pointer hover:bg-[#F0F7FF] transition">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-lg flex items-center justify-center bg-[#FFEBEE] text-[#C23636]">
                    <FiStar />
                  </div>

                  <div>
                    <p className="text-sm font-semibold text-[#0D1B3E]">
                      {tr(
                        'courses.featuredCourse',
                        'Featured Course',
                        'វគ្គសិក្សាពិសេស'
                      )}
                    </p>

                    <p className="text-xs text-[#6B8AFF]">
                      {tr(
                        'courses.featuredHelp',
                        'Display this course in featured sections',
                        'បង្ហាញវគ្គសិក្សានេះនៅផ្នែកវគ្គសិក្សាពិសេស'
                      )}
                    </p>
                  </div>
                </div>

                <input
                  type="checkbox"
                  name="is_featured"
                  checked={
                    courseFormData.is_featured
                  }
                  onChange={
                    handleCourseInputChange
                  }
                  className="w-4 h-4 accent-[#C23636]"
                />
              </label>
            </div>
          </div>

          <div className="mt-6 pt-4 border-t border-[#E8EEF9] flex flex-col-reverse sm:flex-row justify-end gap-3">
            <button
              type="button"
              onClick={closeCourseModal}
              disabled={courseSubmitting}
              className="h-10 px-4 bg-white border border-[#E8EEF9] text-[#6B8AFF] rounded-lg text-sm font-semibold hover:bg-[#F0F7FF] disabled:opacity-50 transition"
            >
              {tr(
                'common.cancel',
                'Cancel',
                'បោះបង់'
              )}
            </button>

            <button
              type="submit"
              disabled={courseSubmitting}
              className="min-w-[140px] h-10 px-5 bg-[#C23636] text-white rounded-lg text-sm font-semibold hover:bg-[#A92E2E] disabled:opacity-50 disabled:cursor-not-allowed transition"
            >
              {courseSubmitting
                ? editingCourse
                  ? tr(
                      'courses.updating',
                      'Updating...',
                      'កំពុងកែប្រែ...'
                    )
                  : tr(
                      'courses.creating',
                      'Creating...',
                      'កំពុងបង្កើត...'
                    )
                : editingCourse
                ? tr(
                    'courses.updateCourse',
                    'Update Course',
                    'រក្សាទុកការកែប្រែ'
                  )
                : tr(
                    'courses.createCourse',
                    'Create Course',
                    'បង្កើតវគ្គសិក្សា'
                  )}
            </button>
          </div>
        </form>
      </AdminModal>

      <AdminModal
        isOpen={categoryModalOpen}
        onClose={closeCategoryModal}
        title={
          editingCategory
            ? tr(
                'courses.editCategory',
                'Edit Category',
                'កែប្រែប្រភេទ'
              )
            : tr(
                'courses.createCategory',
                'Create Category',
                'បង្កើតប្រភេទ'
              )
        }
      >
        <form onSubmit={handleCategorySubmit}>
          <div className="space-y-5">
            <div className="border border-[#E8EEF9] rounded-xl overflow-hidden bg-white">
              <div className="flex items-center gap-2 px-4 py-3 bg-[#F0F7FF] border-b border-[#E8EEF9]">
                <FiGlobe className="text-[#0D1B3E]" />

                <h3 className="text-sm font-bold text-[#0D1B3E]">
                  {isKhmer
                    ? 'មាតិកាភាសាខ្មែរ'
                    : 'English Content'}
                </h3>
              </div>

              <div className="p-4 space-y-4">
                <div>
                  <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                    {isKhmer
                      ? 'ឈ្មោះប្រភេទ'
                      : 'Category Name'}

                    <span className="text-[#C23636] ml-1">
                      *
                    </span>
                  </label>

                  <input
                    type="text"
                    name={`name_${langSuffix}`}
                    value={
                      categoryFormData[
                        `name_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCategoryInputChange
                    }
                    className={`w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'វគ្គសិក្សាព័ត៌មានវិទ្យា'
                        : 'IT Courses'
                    }
                    required
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                    {isKhmer
                      ? 'ការពិពណ៌នា'
                      : 'Description'}
                  </label>

                  <textarea
                    name={`description_${langSuffix}`}
                    value={
                      categoryFormData[
                        `description_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCategoryInputChange
                    }
                    rows={3}
                    className={`w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition resize-none ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'បញ្ចូលការពិពណ៌នាប្រភេទវគ្គសិក្សា'
                        : 'Enter category description'
                    }
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                Slug *
              </label>

              <input
                type="text"
                name="slug"
                value={categoryFormData.slug}
                onChange={
                  handleCategoryInputChange
                }
                className="w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition"
                placeholder="it-courses"
                required
              />
            </div>

            <div>
              <label className="text-sm font-semibold text-[#0D1B3E] block mb-1.5">
                {tr(
                  'courses.displayOrder',
                  'Display Order',
                  'លំដាប់បង្ហាញ'
                )}
              </label>

              <input
                type="number"
                name="order"
                min="0"
                value={categoryFormData.order}
                onChange={
                  handleCategoryInputChange
                }
                className="w-full border border-[#E8EEF9] rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:border-[#0D1B3E] focus:ring-1 focus:ring-[#0D1B3E] transition"
              />
            </div>

            <label className="flex items-center justify-between gap-3 p-4 border border-[#E8EEF9] rounded-xl bg-white cursor-pointer hover:bg-[#F0F7FF] transition">
              <div className="flex items-center gap-3">
                <div
                  className={`
                    w-9
                    h-9
                    rounded-lg
                    flex
                    items-center
                    justify-center
                    ${
                      categoryFormData.is_active
                        ? 'bg-[#EBF9F0] text-[#2E7D32]'
                        : 'bg-[#F0F7FF] text-[#6B8AFF]'
                    }
                  `}
                >
                  {categoryFormData.is_active ? (
                    <FiCheckCircle />
                  ) : (
                    <FiXCircle />
                  )}
                </div>

                <div>
                  <p className="text-sm font-semibold text-[#0D1B3E]">
                    {tr(
                      'courses.activeCategory',
                      'Active Category',
                      'ប្រភេទសកម្ម'
                    )}
                  </p>

                  <p className="text-xs text-[#6B8AFF]">
                    {tr(
                      'courses.activeCategoryHelp',
                      'Show this category on the website',
                      'បង្ហាញប្រភេទនេះនៅលើគេហទំព័រ'
                    )}
                  </p>
                </div>
              </div>

              <input
                type="checkbox"
                name="is_active"
                checked={
                  categoryFormData.is_active
                }
                onChange={
                  handleCategoryInputChange
                }
                className="w-4 h-4 accent-[#0D1B3E]"
              />
            </label>
          </div>

          <div className="mt-6 pt-4 border-t border-[#E8EEF9] flex flex-col-reverse sm:flex-row justify-end gap-3">
            <button
              type="button"
              onClick={closeCategoryModal}
              disabled={categorySubmitting}
              className="h-10 px-4 bg-white border border-[#E8EEF9] text-[#6B8AFF] rounded-lg text-sm font-semibold hover:bg-[#F0F7FF] disabled:opacity-50 transition"
            >
              {tr(
                'common.cancel',
                'Cancel',
                'បោះបង់'
              )}
            </button>

            <button
              type="submit"
              disabled={categorySubmitting}
              className="min-w-[150px] h-10 px-5 bg-[#C23636] text-white rounded-lg text-sm font-semibold hover:bg-[#A92E2E] disabled:opacity-50 disabled:cursor-not-allowed transition"
            >
              {categorySubmitting
                ? editingCategory
                  ? tr(
                      'courses.updating',
                      'Updating...',
                      'កំពុងកែប្រែ...'
                    )
                  : tr(
                      'courses.creating',
                      'Creating...',
                      'កំពុងបង្កើត...'
                    )
                : editingCategory
                ? tr(
                    'courses.updateCategory',
                    'Update Category',
                    'រក្សាទុកការកែប្រែ'
                  )
                : tr(
                    'courses.createCategory',
                    'Create Category',
                    'បង្កើតប្រភេទ'
                  )}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminCourses;
